#include <stdio.h>
#include <ctype.h>
int main(void) {
    char *p = "It is 8";
    char result[100];
    int i;
    for (i = 0; p[i] != '\0'; i++) {
        if (isupper((unsigned char)p[i]))
            result[i] = (p[i] - 'A' + 5) % 25 + 'A';
        else if (islower((unsigned char)p[i]))
            result[i] = (p[i] - 'a' + 10) % 26 + 'a';
        else if (isdigit((unsigned char)p[i]))
            result[i] = (p[i] - '0' + 3) % 10 + '0';
        else
            result[i] = p[i];
    }
    result[i] = '\0';
    printf("%s", result);
    return 0;
}

